1|// Figure placement and picture request rules for one scene. Pure:
2|// no React, no DOM, no network. scene-page.tsx owns the DOM side
3|// (setPage, scroll, pulse) and use-pictures.ts owns the requests.
4|export function groupFiguresByEndN<F extends { endN: number }>(figures: F[]): Map<number, F[]> {
5|  const grouped = new Map<number, F[]>();
6|  for (const fig of figures) {
7|    const list = grouped.get(fig.endN) ?? [];
8|    list.push(fig);
9|    grouped.set(fig.endN, list);
10|  }
11|  return grouped;
12|}
13|
14|// Figures to render after paragraph i of the visible sub-page: only when
15|// it is the last visible fragment of its ordinal on this page. A paragraph
16|// split across pages shows its figures only on the page holding its last
17|// visible fragment there.
18|export function figuresAfter<P extends { n: number }, F>(
19|  paragraphs: P[],
20|  i: number,
21|  grouped: Map<number, F[]>,
22|): F[] {
23|  const cur = paragraphs[i];
24|  if (!cur) return [];
25|  return paragraphs[i + 1]?.n !== cur.n ? (grouped.get(cur.n) ?? []) : [];
26|}
27|
28|// Index of the sub-page holding paragraph ordinal n, -1 when none.
29|export function pageOfOrdinal<P extends { n: number }>(pages: { paragraphs: P[] }[], n: number): number {
30|  return pages.findIndex((p) => p.paragraphs.some((para) => para.n === n));
31|}
32|
33|// One request at a time across scene and figure. The flag lives in the
34|// caller's ref; these are the only transitions.
35|export function tryStart(gate: { current: boolean }): boolean {
36|  if (gate.current) return false;
37|  gate.current = true;
38|  return true;
39|}
40|
41|export function finish(gate: { current: boolean }): void {
42|  gate.current = false;
43|}
44|
45|export function canStart(busy: boolean): boolean {
46|  return !busy;
47|}
48|
49|// A figure retries only from the error phase, never while busy.
50|export function canRetryFigure<F extends { phase: string }>(figure: F | undefined, busy: boolean): figure is F {
51|  return !busy && figure?.phase === "error";
52|}
53|
54|// A scene illustrates only with an id, no request in flight, nothing cached.
55|export function canIllustrateScene(args: { sceneId: string; busy: boolean; cached: boolean }): boolean {
56|  return args.sceneId !== "" && !args.busy && !args.cached;
57|}

